/**
 * routeHandoff.js — one-shot state handed from the page you clicked FROM to the page
 * you land ON.
 *
 * WHY NOT A QUERY PARAM
 *   The obvious shape is `#/leads?campaign=spring`. It doesn't survive: mvvLegit owns
 *   the fragment and strips unknown tails during its route guard, so params vanish
 *   before the destination route ever reads them (see the mvvlegit-auth notes — the
 *   same trap behind "params disappear from the URL" and email-link landings).
 *
 * WHY ONE-SHOT
 *   Claiming clears the value. Without that, a drill-through would silently re-apply
 *   itself every later visit to the destination — you'd search for a campaign once and
 *   find the leads page mysteriously filtered days later.
 *
 * TRADEOFF, STATED PLAINLY
 *   This is in-memory module state, so it does not survive a reload or a new tab. A
 *   middle-clicked drill-through lands on the unfiltered destination. That is a
 *   deliberate, graceful degradation rather than a bug: the alternative is persisting
 *   UI intent to storage, which then needs its own expiry and staleness rules.
 *
 * Second use of this pattern (magnet templates → /magnets was the first), extracted at
 * instance two for the same reason stepTypes.js and magnetAppearance.js exist.
 */

// Keys are declared here rather than passed as loose strings, so a typo is a missing
// import instead of a hand-off that silently never arrives.
export const HANDOFF = Object.freeze({
  /** Template id chosen on /templates, claimed by /magnets to start that flow. */
  MAGNET_TEMPLATE: 'magnet_template',
  /** Search text set from a dashboard drill-through, claimed by /leads. */
  LEADS_SEARCH: 'leads_search',
  /**
   * A single YYYY-MM-DD day, set by clicking a column on the dashboard's trend
   * chart, claimed by /leads. UTC, matching how the chart's own buckets are keyed —
   * see the day filter in leads-route.
   */
  LEADS_DAY: 'leads_day',
});

const pending = new Map();

export function setHandoff(key, value) {
  pending.set(key, value);
}

/** Read and clear. Returns null when nothing is waiting. */
export function takeHandoff(key) {
  if (!pending.has(key)) return null;
  const value = pending.get(key);
  pending.delete(key);
  return value;
}

/**
 * Read WITHOUT clearing. For callers that need to know what is parked but are not
 * the claimant — a page rendering "you picked X" before the destination route runs,
 * or a staleness check that must not burn the one delivery takeHandoff() grants.
 * Returns null when nothing is waiting.
 */
export function peekHandoff(key) {
  if (!pending.has(key)) return null;
  return pending.get(key);
}

/** Drop a parked value without consuming it (e.g. the user navigated elsewhere). */
export function clearHandoff(key) {
  pending.delete(key);
}

export default { HANDOFF, setHandoff, takeHandoff, peekHandoff, clearHandoff };
